<?php
require __DIR__.'/config.php';
$me=require_staff();
$id=(int)($_GET['transaction_id']??0);
$sql="SELECT t.transaction_id,t.reference_number,t.account_id,t.transaction_type,t.amount,t.balance_before,t.balance_after,t.related_account_id,t.description,t.status,t.created_at,a.account_number,a.account_title,a.currency,a.branch_id,at.type_name,b.branch_name,c.customer_id,c.full_name AS customer_name,c.cif_number,c.phone,e.full_name AS staff_name,e.position AS staff_position FROM transactions t JOIN accounts a ON a.account_id=t.account_id JOIN branches b ON b.branch_id=a.branch_id LEFT JOIN account_types at ON at.account_type_id=a.account_type_id LEFT JOIN account_holders h ON h.account_id=a.account_id AND h.holder_role='primary' LEFT JOIN customers c ON c.customer_id=h.customer_id LEFT JOIN users u ON u.user_id=t.performed_by_user_id LEFT JOIN employees e ON e.employee_id=u.linked_employee_id WHERE t.transaction_id=? AND t.status='completed'";
$s=db()->prepare($sql);$s->execute([$id]);$tx=$s->fetch();
if(!$tx||($me['role']!=='Administrator'&&(int)$tx['branch_id']!==(int)$me['branch_id'])){http_response_code(404);exit('Transaction slip not found.');}
$transfer=in_array($tx['transaction_type'],['transfer_out','transfer_in'],true);$from=$to=null;$linked='';$fee=0.0;
if($transfer){
 $counter=db()->prepare("SELECT t.transaction_id,t.reference_number,t.account_id,t.transaction_type,t.amount,t.balance_before,t.balance_after,a.account_number,a.account_title,a.currency,a.branch_id,at.type_name,b.branch_name,c.customer_id,c.full_name AS customer_name,c.cif_number,c.phone FROM transactions t JOIN accounts a ON a.account_id=t.account_id JOIN branches b ON b.branch_id=a.branch_id LEFT JOIN account_types at ON at.account_type_id=a.account_type_id LEFT JOIN account_holders h ON h.account_id=a.account_id AND h.holder_role='primary' LEFT JOIN customers c ON c.customer_id=h.customer_id WHERE t.account_id=? AND t.transaction_id=? AND t.status='completed'");
 $counter->execute([(int)$tx['related_account_id'],0]);$other=$counter->fetch();
 // The linked ledger entry is found through the transfer record, never by guessing from a reference string.
 $link=db()->prepare('SELECT debit_transaction_id,credit_transaction_id,fee FROM transfers WHERE debit_transaction_id=? OR credit_transaction_id=? LIMIT 1');$link->execute([$id,$id]);$pair=$link->fetch();
 if($pair){$otherId=(int)($pair['debit_transaction_id']==$id?$pair['credit_transaction_id']:$pair['debit_transaction_id']);$counter->execute([(int)$tx['related_account_id'],$otherId]);$other=$counter->fetch();$linked=(string)($other['reference_number']??'');$fee=(float)$pair['fee'];}
 if(!$other||($me['role']!=='Administrator'&&(int)$other['branch_id']!==(int)$me['branch_id'])){http_response_code(404);exit('Transfer slip not found.');}
 if($tx['transaction_type']==='transfer_out'){$from=$tx;$to=$other;}else{$from=$other;$to=$tx;}
}
function slip_words_under_1000(int $n):string{$ones=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];$tens=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];$w=[];if($n>=100){$w[]=$ones[intdiv($n,100)];$w[]='hundred';$n%=100;}if($n>=20){$w[]=$tens[intdiv($n,10)];if($n%10)$w[]=$ones[$n%10];}elseif($n>0)$w[]=$ones[$n];return implode(' ',$w);}
function slip_words(int $n):string{if($n===0)return 'Zero';$scales=['','thousand','million','billion','trillion'];$parts=[];$i=0;while($n>0&&$i<count($scales)){$chunk=$n%1000;if($chunk)$parts[]=slip_words_under_1000($chunk).($scales[$i]?' '.$scales[$i]:'');$n=intdiv($n,1000);$i++;}return ucfirst(implode(' ',array_reverse($parts)));}
$amount=(float)$tx['amount'];$whole=(int)floor($amount);$cents=(int)round(($amount-$whole)*100);$words='Taka '.ucwords(slip_words($whole)).($cents?' and '.slip_words($cents).' Paisa':'').' Only';
$kind=match($tx['transaction_type']){'deposit'=>'Deposit','withdrawal'=>'Withdrawal','transfer_out'=>'Transfer Out','transfer_in'=>'Transfer In','fee'=>'Fee','interest'=>'Interest',default=>ucwords(str_replace('_',' ',$tx['transaction_type']))};
$performed=$tx['staff_name']?($tx['staff_name'].' (Employee, '.$tx['staff_position'].')'):($tx['customer_name']??'BankEase Staff');
$particulars=$tx['description']?:($transfer?'Transfer to '.$to['customer_name']:'Cash '.$kind.' at counter');
