rid-template-columns:1fr 1fr 1fr;gap:8mm;padding:0 0 1.5mm}.sign{text-align:center;border-top:1px solid #444;color:#687080;font-size:7pt;padding-top:1mm}.foot{text-align:center;color:#737c89;font-size:6.5pt}.print{display:block}@page{size:200mm 120mm;margin:0}@media print{html,body{width:200mm;height:120mm;background:#fff}.toolbar{display:none}.slip{margin:0;width:200mm;height:120mm;box-shadow:none;print-color-adjust:exact;-webkit-print-color-adjust:exact}}
