<?php if($transfer):?><section class="details"><div class="box"><h2>FROM (DEBIT) ACCOUNT</h2><div class="rows"><div class="row"><span class="k">Account No.</span><span class="v"><?=e($from['account_number'])?></span></div><div class="row"><span class="k">Account Title</span><span class="v"><?=e($from['account_title'])?></span></div><div class="row"><span class="k">Customer</span><span class="v"><?=e($from['customer_name']??'—')?><?=!empty($from['cif_number'])?' (CIF '.e($from['cif_number']).')':''?></span></div><div class="row"><span class="k">Balance Before</span><span class="v">BDT <?=number_format((float)$from['balance_before'],2)?></span></div><div class="row"><span class="k">Balance After</span><span class="v">BDT <?=number_format((float)$from['balance_after'],2)?></span></div></div></div><div class="box"><h2>TO (CREDIT) ACCOUNT</h2><div class="rows"><div class="row"><span class="k">Account No.</span><span class="v"><?=e($to['account_number'])?></span></div><div class="row"><span class="k">Account Title</span><span class="v"><?=e($to['account_title'])?></span></div><div class="row"><span class="k">Customer</span><span class="v"><?=e($to['customer_name']??'—')?><?=!empty($to['cif_number'])?' (CIF '.e($to['cif_number']).')':''?></span></div><div class="row"><span class="k">Balance Before</span><span class="v">BDT <?=number_format((float)$to['balance_before'],2)?></span></div><div class="row"><span class="k">Balance After</span><span class="v">BDT <?=number_format((float)$to['balance_after'],2)?></span></div></div></div></section>
<section class="amounts"><div class="cell amount-main"><div class="label">Amount (Figures) - Debit</div><div class="value">BDT <?=number_format($amount,2)?></div></div><div class="cell"><div class="label">Transfer Type</div><div class="value">Internal<?= $fee>0?' (fee BDT '.number_format($fee,2).')':''?></div></div><div class="cell"><div class="label">Linked Reference</div><div class="value"><?=e($linked?:'—')?></div></div></section>
<?php else:?><section class="details"><div class="box"><h2>ACCOUNT DETAILS</h2><div class="rows"><div class="row"><span class="k">Account No.</span><span class="v"><?=e($tx['account_number'])?></span></div><div class="row"><span class="k">Account Title</span><span class="v"><?=e($tx['account_title'])?></span></div><div class="row"><span class="k">Account Type</span><span class="v"><?=e($tx['type_name']??'—')?></span></div><div class="row"><span class="k">Branch</span><span class="v"><?=e($tx['branch_name'])?></span></div><div class="row"><span class="k">Currency</span><span class="v"><?=e($tx['currency'])?></span></div></div></div><div class="box"><h2>CUSTOMER DETAILS</h2><div class="rows"><div class="row"><span class="k">Customer Name</span><span class="v"><?=e($tx['customer_name']??'—')?></span></div><div class="row"><span class="k">CIF Number</span><span class="v"><?=e($tx['cif_number']??'—')?></span></div><div class="row"><span class="k">Phone</span><span class="v"><?=e($tx['phone']??'—')?></span></div><div class="row"><span class="k">Particulars</span><span class="v"><?=e($particulars)?></span></div></div></div></section>
<section class="amounts"><div class="cell amount-main"><div class="label">Amount (Figures) - <?= $tx['transaction_type']==='deposit'?'Credit':'Debit'?></div><div class="value">BDT <?=number_format($amount,2)?></div></div><div class="cell"><div class="label">Balance Before</div><div class="value">BDT <?=number_format((float)$tx['balance_before'],2)?></div></div><div class="cell"><div class="label">Balance After</div><div class="value">BDT <?=number_format((float)$tx['balance_after'],2)?></div></div></section><?php endif;?>
<div class="note"><strong>IN WORDS:</strong><b><?=e($words)?></b></div><div class="perform"><p><strong>Performed by:</strong> <?=e($performed)?></p><?php if($transfer||$tx['description']):?><p><strong>Particulars:</strong> <?=e($particulars)?></p><?php endif;?></div><div class="signs"><div class="sign"><?=$transfer?'Sender':'Depositor'?>'s Signature</div><div class="sign">Teller / Cashier</div><div class="sign">Authorised Signatory</div></div><div class="foot">Computer-generated slip · BankEase · Ref <?=e($tx['reference_number'])?> · Printed <?=e(date('Y-m-d H:i:s'))?></div></article></body></html>
